import numpy as np


def q212(latencies, success, duration):
    x = np.asarray(latencies, float)
    return {
        "requests": len(x),
        "success_rate": float(np.mean(success)),
        "throughput": len(x) / duration,
        "latency_percentiles": np.percentile(x, [50, 95, 99]),
    }
